import itertools

B = list(range(100))

# P1_1: f - g
P1_1 = set()
for f in B:
    for g in B:
        P1_1.add(f - g)

# P1_2: 3pq (Assuming the notation 3pqr means 3*p*q, since only p and q are mentioned)
P1_2 = set()
for p in P1_1:
    for q in P1_1:
        P1_2.add(3 * p * q)

# P1_3: x^2 + y^2 - z^2 - w^2
P1_3 = set()
for x in P1_1:
    for y in P1_1:
        for z in P1_1:
            for w in P1_1:
                P1_3.add(x**2 + y**2 - z**2 - w**2)

print(f"Size of P1_1: {len(P1_1)}")
print(f"Min/Max P1_2: {min(P1_2)}, {max(P1_2)}")
print(f"Size of P1_3: {len(P1_3)}")
print(f"Check P1_2 subset P1_3: {P1_2.issubset(P1_3)}")

